#include <iostream>
#include <vector>
#include <deque>
#include <cstring>
#include <climits>
#include <algorithm>
using namespace std;

char boardA[12][12], boardB[12][12];
int dim, limit;
bool seen[70][12][12][12][12];
bool accessible[12][12][12][12];
int timeCost[12][12];
vector<vector<int>> network;
int cap[210][210], f[210][210];
int supply[210], level[210];
int vertex[11][11];

void trace(int step, int r, int c, int sr, int sc) {
    if (limit >= 70) return;
    if (r < 0 || r >= dim || c < 0 || c >= dim) return;
    if (boardA[r][c] < '0' || boardA[r][c] > '9') return;
    if (step > limit + 1) return;
    if (seen[step][r][c][sr][sc]) return;
    if (step > timeCost[r][c] && timeCost[r][c] != 0) return;
    if (step == timeCost[r][c] && timeCost[r][c] != 0 && (boardB[r][c] > '9' || boardB[r][c] <= '0')) return;
    seen[step][r][c][sr][sc] = true;
    if (step < timeCost[r][c]) {
        trace(step+1, r, c, sr, sc);
        trace(step+1, r+1, c, sr, sc);
        trace(step+1, r-1, c, sr, sc);
        trace(step+1, r, c+1, sr, sc);
        trace(step+1, r, c-1, sr, sc);
    }
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("1.txt", "rt", stdin);
#endif
    cin >> dim >> limit;
    for (int i = 0; i < dim; ++i)
        for (int j = 0; j < dim; ++j)
            cin >> boardA[i][j];
    for (int i = 0; i < dim; ++i)
        for (int j = 0; j < dim; ++j)
            cin >> boardB[i][j];

    deque<pair<int,int>> q;
    memset(timeCost, -1, sizeof(timeCost));
    for (int i = 0; i < dim; ++i)
        for (int j = 0; j < dim; ++j)
            if (boardA[i][j] == 'Z') {
                timeCost[i][j] = 0;
                q.emplace_back(i, j);
            }

    const int dr[4] = {-1, 0, 1, 0};
    const int dc[4] = {0, -1, 0, 1};
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop_front();
        if (timeCost[r][c] >= limit) continue;
        for (int d = 0; d < 4; ++d) {
            int nr = r + dr[d], nc = c + dc[d];
            if (nr >= 0 && nr < dim && nc >= 0 && nc < dim &&
                boardA[nr][nc] >= '0' && boardA[nr][nc] <= '9' && timeCost[nr][nc] == -1) {
                timeCost[nr][nc] = timeCost[r][c] + 1;
                q.emplace_back(nr, nc);
            }
        }
    }
    for (int i = 0; i < dim; ++i)
        for (int j = 0; j < dim; ++j)
            if (timeCost[i][j] == -1) timeCost[i][j] = limit;

    for (int i = 0; i < dim; ++i)
        for (int j = 0; j < dim; ++j)
            if (boardA[i][j] >= '0' && boardA[i][j] <= '9')
                trace(0, i, j, i, j);

    for (int i1 = 0; i1 < dim; ++i1)
        for (int j1 = 0; j1 < dim; ++j1)
            for (int i2 = 0; i2 < dim; ++i2)
                for (int j2 = 0; j2 < dim; ++j2)
                    for (int s = 0; s <= limit; ++s)
                        accessible[i1][j1][i2][j2] |= seen[s][i1][j1][i2][j2];

    network.resize(1);
    for (int i1 = 0; i1 < dim; ++i1)
        for (int j1 = 0; j1 < dim; ++j1)
            if (boardA[i1][j1] > '0' && boardA[i1][j1] <= '9') {
                int u = network.size();
                network.emplace_back();
                supply[u] = boardA[i1][j1] - '0';
                for (int i2 = 0; i2 < dim; ++i2)
                    for (int j2 = 0; j2 < dim; ++j2)
                        if (boardB[i2][j2] > '0' && boardB[i2][j2] <= '9' && accessible[i2][j2][i1][j1]) {
                            int v;
                            if (vertex[i2][j2] == 0) {
                                vertex[i2][j2] = network.size();
                                network.emplace_back();
                            }
                            v = vertex[i2][j2];
                            network[u].push_back(v);
                            network[v].push_back(u);
                            cap[u][v] = 10000;
                            cap[v][u] = 0;
                        }
            }

    for (int i2 = 0; i2 < dim; ++i2)
        for (int j2 = 0; j2 < dim; ++j2)
            if (boardB[i2][j2] > '0' && boardB[i2][j2] <= '9' && vertex[i2][j2] > 0) {
                int v = vertex[i2][j2];
                network[v].push_back(0);
                cap[v][0] = boardB[i2][j2] - '0';
                cap[0][v] = 0;
            }

    for (int i = 0; i < (int)network.size(); ++i) level[i] = 0;
    level[0] = network.size();

    while (true) {
        bool modified = false;
        for (int u = 1; u < (int)network.size(); ++u) {
            while (supply[u] > 0) {
                bool pushed = false;
                int minL = INT_MAX;
                for (int v : network[u]) {
                    if (cap[u][v] - f[u][v] > 0) minL = min(minL, level[v]);
                    if (cap[u][v] - f[u][v] > 0 && level[u] == level[v] + 1) {
                        int delta = min(cap[u][v] - f[u][v], supply[u]);
                        f[u][v] += delta;
                        f[v][u] -= delta;
                        supply[u] -= delta;
                        supply[v] += delta;
                        pushed = true;
                        modified = true;
                        if (supply[u] == 0) goto endLoop;
                    }
                }
                if (level[u] != minL + 1 && minL != INT_MAX) {
                    level[u] = minL + 1;
                    modified = true;
                }
                if (!pushed) endLoop: break;
            }
        }
        if (!modified) break;
    }

    cout << supply[0];
    return 0;
}
